for (size_t i = start; i < end; ++i) {
    Particle &p = particles[i];
    float density = selfDens;
    for (int x = -1; x <= 1; ++x) {
        for (int y = -1; y <= 1; ++y) {
            for (int z = -1; z <= 1; ++z) {
                uint32_t index = particleTable[(p.position[0] + x) * 256 + (p.position[1] + y) * 16 + (p.position[2] + z)];
                for (uint32_t j = index; j < index + 8; ++j) {
                    Particle &neighbor = particles[j];
                    float r2 = (p.position[0] - neighbor.position[0]) * (p.position[0] - neighbor.position[0]) +
                              (p.position[1] - neighbor.position[1]) * (p.position[1] - neighbor.position[1]) +
                              (p.position[2] - neighbor.position[2]) * (p.position[2] - neighbor.position[2]);
                    if (r2 < h2) {
                        density += mass * poly6 * std::pow(h2 - r2, 3);
                    }
                }
            }
        }
    }
    p.density = density;
    p.pressure = gasConstant * (density - restDensity);
}

